#!/usr/bin/env python3
"""Generate offline Web and native catalogues from locales/en.json."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
catalog = json.loads((ROOT / "locales/en.json").read_text(encoding="utf-8"))
assert all(isinstance(k, str) and k and isinstance(v, str) and v for k, v in catalog.items())
data = json.dumps(catalog, ensure_ascii=False, indent=2)
outputs = {
    ROOT / "apps/desktop/web/i18n-catalog.js":
        "// Generated by scripts/sync-localizations.py; edit locales/en.json.\n"
        + "globalThis.AieyesMessages = " + data + ";\n",
    ROOT / "apps/macos/Sources/Aieyes/LocalizationCatalog.swift":
        "// Generated by scripts/sync-localizations.py; edit locales/en.json.\n"
        + "import Foundation\n\nenum LocalizationCatalog {\n"
        + '    static let english: [String: String] = (try? JSONDecoder().decode([String: String].self, from: Data(#"""\n'
        + data + '\n"""#.utf8))) ?? [:]\n}\n',
}
for path, content in outputs.items():
    if "--check" in sys.argv:
        assert path.exists() and path.read_text(encoding="utf-8") == content, f"Stale localization: {path}"
    else:
        path.write_text(content, encoding="utf-8")
print(f"Web/native localization catalogues agree ({len(catalog)} messages)")
